import { db } from "../lib/db";
import { decryptSecret } from "../lib/crypto-box";
import { Client } from "ssh2";

const SERVER_ID = "cmsecmdps0001hlp27ai6mr7c";
const EXPECT_IP = "51.79.226.215";

function run(conn: Client, cmd: string): Promise<{ code: number; out: string; err: string }> {
  return new Promise((resolve, reject) => {
    conn.exec(cmd, (e, stream) => {
      if (e) return reject(e);
      let out = "";
      let err = "";
      stream.on("close", (code: number) => resolve({ code, out, err }));
      stream.on("data", (d: Buffer) => (out += d.toString()));
      stream.stderr.on("data", (d: Buffer) => (err += d.toString()));
    });
  });
}

async function main() {
  const cmd = process.argv.slice(2).join(" ");
  if (!cmd) {
    console.error("usage: tsx nexis-ssh.ts <shell command>");
    process.exit(2);
  }
  const s = await db.server.findUnique({
    where: { id: SERVER_ID },
    select: { id: true, name: true, ipAddress: true, sshPort: true, rootPasswordEnc: true },
  });
  if (!s) throw new Error("NO SERVER");
  if (s.ipAddress !== EXPECT_IP) throw new Error(`IP ASSERT FAILED: got ${s.ipAddress} expected ${EXPECT_IP}`);
  const pw = decryptSecret(s.rootPasswordEnc);
  await db.$disconnect();

  const conn = new Client();
  await new Promise<void>((resolve, reject) => {
    conn.on("ready", () => resolve());
    conn.on("error", reject);
    conn.connect({ host: s.ipAddress, port: s.sshPort ?? 22, username: "root", password: pw, readyTimeout: 30000 });
  });
  const r = await run(conn, cmd);
  conn.end();
  if (r.out) process.stdout.write(r.out);
  if (r.err) process.stderr.write(r.err);
  process.exit(r.code);
}
main().catch((e) => { console.error(e); process.exit(1); });

