import { db } from "../lib/db";
import { decryptSecret } from "../lib/crypto-box";
import { Client } from "ssh2";
import { readFileSync } from "node:fs";

const SERVER_ID = "cmsecmdps0001hlp27ai6mr7c";
const EXPECT_IP = "51.79.226.215";

// Upload one or more local files to remote paths.
// usage: tsx nexis-put.ts <local1> <remote1> [<local2> <remote2> ...]
async function main() {
  const args = process.argv.slice(2);
  if (args.length < 2 || args.length % 2 !== 0) {
    console.error("usage: tsx nexis-put.ts <local> <remote> [<local> <remote> ...]");
    process.exit(2);
  }
  const s = await db.server.findUnique({
    where: { id: SERVER_ID },
    select: { ipAddress: true, sshPort: true, rootPasswordEnc: true },
  });
  if (!s) throw new Error("NO SERVER");
  if (s.ipAddress !== EXPECT_IP) throw new Error(`IP ASSERT FAILED: ${s.ipAddress}`);
  const pw = decryptSecret(s.rootPasswordEnc);
  await db.$disconnect();

  const conn = new Client();
  await new Promise<void>((resolve, reject) => {
    conn.on("ready", () => resolve());
    conn.on("error", reject);
    conn.connect({ host: s.ipAddress, port: s.sshPort ?? 22, username: "root", password: pw, readyTimeout: 30000 });
  });
  const sftp = await new Promise<import("ssh2").SFTPWrapper>((resolve, reject) =>
    conn.sftp((e, sf) => (e ? reject(e) : resolve(sf)))
  );
  for (let i = 0; i < args.length; i += 2) {
    const local = args[i];
    const remote = args[i + 1];
    const buf = readFileSync(local);
    await new Promise<void>((resolve, reject) => {
      const ws = sftp.createWriteStream(remote);
      ws.on("close", () => resolve());
      ws.on("error", reject);
      ws.end(buf);
    });
    console.log(`PUT ${local} -> ${remote} (${buf.length} bytes)`);
  }
  conn.end();
}
main().catch((e) => { console.error(e); process.exit(1); });

import path from "path";

// Root directory for tenant media uploads.
//
// This MUST be environment-aware: prod and staging run from different working
// trees but historically both hardcoded "/opt/nexis/uploads", so the staging
// app wrote uploaded photos straight into PROD's uploads dir (cross-environment
// pollution). Driving it from an env var fixes that with zero risk to prod.
//
//   UPLOADS_DIR  — absolute path to this deployment's uploads dir.
//   default      — "/opt/nexis/uploads", the original prod location, so prod
//                  keeps its exact existing path with no env change required.
//
// Staging sets UPLOADS_DIR=/opt/nexis-staging/uploads in its own .env, so it
// now writes to (and serves from) its own directory.
export const UPLOADS_ROOT = process.env.UPLOADS_DIR?.trim()
  ? path.resolve(process.env.UPLOADS_DIR.trim())
  : "/opt/nexis/uploads";

// Canonical public URL for a studio's booking/website. Every "view your site"
// link in the app must go through here so we never leak the internal
// /s/<slug> form. Custom domain wins ONLY once it is verified & live; otherwise
// the studio's subdomain <slug>.<base domain>. Pure (no db) so it's safe in
// client components too.
//
// Domain lifecycle: setting a custom domain stores it on the tenant and marks
// policies.domain.status = "PENDING_DNS". It must only take over the public URL
// once verification promotes it to "LIVE" — otherwise an unverified (or
// mis-pointed / cert-less) domain would hijack every booking link and break
// them. So we gate on that status here.
import { BASE_DOMAIN } from "@/lib/config";

const BASE = BASE_DOMAIN;

type DomainPolicy = { domain?: { status?: string } | null } | null | undefined;

export function publicSiteUrl(
  tenant: { slug: string; customDomain?: string | null; policies?: unknown },
  path = "",
): string {
  const domainLive =
    (tenant.policies as DomainPolicy)?.domain?.status === "LIVE";
  const origin =
    tenant.customDomain && domainLive
      ? `https://${tenant.customDomain}`
      : `https://${tenant.slug}.${BASE}`;
  if (!path) return origin;
  return `${origin}${path.startsWith("/") ? "" : "/"}${path}`;
}

